  @state GUTTER_PAD = 14  @ 31
  @state LOOP_PAD = 7  @ 34
  @state SLOT_KEY_W, SLOT_KIND_W = 18, 16  @ 36
  @state press = nil  @ 45
      @invariant  drag relocates via am:startIsClear; cursor moves only on clean (no-drag) release.  @ 42
      @invariant  gutter press drives REAPER transport — release sets edit cursor, drag sets loop range.  @ 43
      @invariant  double-click on empty space starts a create press; release opens create modal.  @ 44
  @state WHEEL_STEP_ROWS = 1  @ 46   -- viewport rows panned per mouse-wheel notch
  @state WHEEL_STEP_COLS = 0.5  @ 47   -- viewport cols panned per mouse-wheel notch
  @state wheelAccumV = 0  @ 48   -- fractional vertical wheel carried between frames
  @state wheelAccumH = 0  @ 49   -- fractional horizontal wheel carried between frames
  @state SLOT_FILL_ALPHA = 1  @ 79
  @state colourCache = {}  @ 80
  @state peakCache = {}  @ 100
  @state HEADER_PAD = 8  @ 177
  @state HEADER_GAP = 4  @ 178
  @state toolbarSegments = {  @ 754
  @state arrange = cmgr:scope('arrange')  @ 840
      @invariant  createSlot (Ctrl+Enter) opens the create modal — the only slot-minting gesture.  @ 838

# Private functions
  @fn drainWheel(accum, wheel, unitsPerNotch)  @ 53-57
      -- Accumulate a fractional wheel delta and drain whole notches off it.
      -- Returns the residual accumulator and the integer step to apply.
  -- Style + draw helpers
  @fn pushBodyStyles()  @ 61-68
  @fn popBodyStyles()  @ 69
  @fn rowLabel(row)  @ 73-75
      -- Row label = QN at the row's top edge. beatPerRow is integer-valued
      -- in normal use (1, 4, 8, 16); show the QN as an integer.
  @fn slotFill(colourIdx, focused)  @ 81-94
  -- Audio waveform previews (native REAPER peaks)
  @fn takeWindowSec(take, startQN, lengthQN)  @ 104-110
      -- Window keyed to drawn length (not D_LENGTH) so scale stays fixed on resize:
      -- head anchored, tail reveals/hides like a trim.
  @fn peaksFor(take, startQN, lengthQN, pxPerSec, loop)  @ 115-166
      -- PCM_Source_GetPeaks: maxes block then mins block, channels interleaved per column;
      -- reduce to per-column signed hi/lo. Loops sample ONE source period; others map the window.
      @contract  nil for an unreadable source; entry with hi=nil while peaks still build  @ 114
  -- MIDI note previews (channel→X, time→Y; note-on caps darker than bodies)
  -- Grid pane
  @fn floorTo(v, step)  @ 181
      -- Snap a click's QN down to the top edge of the row box it sits in.
  @fn gridGeom(nTracks)  @ 185-213
      -- Shared (col,row)→screen transform for mouse pass and paint pass: both call gridGeom at the
      -- same layout-cursor position, so hit-test and draw resolve through one mapping.
  @fn handleGridMouse(nTracks)  @ 217-321
      -- Runs before renderGrid so in-flight drag/loop/create candidates are ready for the paint pass.
      -- Must run inside ##arrangeGrid so IsWindowHovered resolves correctly.
  @fn renderGrid(tracks, nTracks, dragCand, loopCand, createCand, lassoCand)  @ 323-612
  -- Palette pane
  @fn focusedSlotEntry(slots, slotIdx)  @ 618-624
      -- Locate slot in trackSlots() output (packed array, not indexed by slotIdx).
      -- Returns nil when no slot is focused or the focused slot index isn't populated.
  @fn paletteTrackLabel(focusedTrack)  @ 626-631
  @fn openRenameModal(trackIdx, slotIdx, currentName)  @ 633-640
  @fn openDeleteModal(trackIdx, slot)  @ 642-651
  @fn openCreateModal(trackIdx, qnPos, beats)  @ 655-668
      -- Length seeds from a drag-sweep when given, else the project-tier newTakeBeats
      -- config; the committed length persists back to it.
  @fn renderPaletteActions(focusedTrack, focusedSlot)  @ 691-706
  @fn renderPaletteList(slots)  @ 710-741
      -- Three columns: key (monospace — hotkey), kind glyph, name (UI font).
      -- Selectable in col 0 with SpanAllColumns; key text painted on top via SameLine.
  @fn renderPaletteBody(focusedTrack)  @ 743-749

